-- POSTCHECK 022 — Music V0 — LECTURE SEULE (aucune écriture).
-- Généré depuis une base locale jetable construite avec les fichiers poussés
-- (HEAD 10369f828f2144cf2d4181a84cc561dfefa1aab6). Résultat attendu : "conforme": true.
with attendu as (select '{"colonnes": {"music_brief_versions": ["order_id:uuid:true", "version:integer:true", "contenu:jsonb:true", "sent_at:timestamp with time zone:true", "client_feedback:text:false", "correction_requested_at:timestamp with time zone:false", "validated_at:timestamp with time zone:false"], "music_briefs": ["id:uuid:true", "order_id:uuid:true", "version:integer:true", "contenu:jsonb:true", "created_at:timestamp with time zone:true", "updated_at:timestamp with time zone:true", "sent_at:timestamp with time zone:false", "client_feedback:text:false", "correction_requested_at:timestamp with time zone:false", "validated_at:timestamp with time zone:false", "validated_version:integer:false", "validation_consent_version:text:false"]}, "contraintes": {"music_brief_versions": ["music_brief_versions_contenu_valide:c", "music_brief_versions_feedback_complet:c", "music_brief_versions_issue_unique:c", "music_brief_versions_order_id_fkey:f:music_orders:ondelete=c", "music_brief_versions_pkey:p"], "music_briefs": ["music_briefs_consent_version_format:c", "music_briefs_contenu_valide:c", "music_briefs_correction_apres_envoi:c", "music_briefs_feedback_complet:c", "music_briefs_feedback_longueur:c", "music_briefs_order_id_fkey:f:music_orders:ondelete=c", "music_briefs_order_id_key:u", "music_briefs_pkey:p", "music_briefs_validation_coherente:c", "music_briefs_validation_complete:c", "music_briefs_version_positive:c"]}, "fonctions": {"music_admin_brief_enregistrer(text,jsonb)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "5aa7adf06b4ab61a5defb4f62c20df9a", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_admin_brief_envoyer(text,text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "f291f54c6863be5e73641d217019b29f", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_admin_brief_suivi(text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "293920c5ddb121065d82a06e91080294", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "s"}, "music_admin_questionnaire(text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "6fdb9f154db3f21129aa1320f9ffb0d7", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "s"}, "music_brief_charger(text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "6a9125eede4a20778d0933184f2a6353", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "s"}, "music_brief_contenu_erreur(jsonb)": {"config": ["search_path=public, pg_temp"], "execute": [], "md5_corps": "403f4da5e3ee355262510a7a9f14d77b", "proprietaire": "postgres", "retour": "text", "security_definer": false, "volatilite": "i"}, "music_brief_corriger(text,integer,text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "5e2709ddc44c62d1e9bed0fabb3e9e3e", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}, "music_brief_valider(text,integer,text)": {"config": ["search_path=public, pg_temp"], "execute": ["service_role"], "md5_corps": "a0c6db0540a6924607abad6705e16638", "proprietaire": "postgres", "retour": "json", "security_definer": true, "volatilite": "v"}}, "index": {"music_brief_versions": ["music_brief_versions_pkey:unique=true"], "music_briefs": ["music_briefs_order_id_key:unique=true", "music_briefs_pkey:unique=true"]}, "policies": 0, "privileges_hors_proprietaire": {"music_brief_versions": [], "music_briefs": []}, "proprietaires": {"music_brief_versions": "postgres", "music_briefs": "postgres"}, "rls": {"music_brief_versions": true, "music_briefs": true}, "sequences": {}, "tables_presentes": ["music_brief_versions", "music_briefs"], "triggers": 0}'::jsonb as e),
     reel as (
    select jsonb_build_object(
      'tables_presentes', (select coalesce(jsonb_agg(relname order by relname), '[]') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname = any(array['music_briefs','music_brief_versions']::text[])),
      'proprietaires', (select coalesce(jsonb_object_agg(relname, pg_get_userbyid(relowner)), '{}') from pg_class where relnamespace = 'public'::regnamespace and relname = any(array['music_briefs','music_brief_versions']::text[] || array['__aucune__']::text[])),
      'colonnes', (select coalesce(jsonb_object_agg(c.relname, (select jsonb_agg(a.attname || ':' || format_type(a.atttypid, a.atttypmod) || ':' || a.attnotnull::text order by a.attnum) from pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped)), '{}')
                   from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_briefs','music_brief_versions']::text[])),
      'contraintes', (select coalesce(jsonb_object_agg(c.relname, (select jsonb_agg(k.conname || ':' || k.contype::text || case when k.contype = 'f' then ':' || k.confrelid::regclass::text || ':ondelete=' || k.confdeltype::text else '' end order by k.conname) from pg_constraint k where k.conrelid = c.oid and k.contype <> 'n')), '{}')
                      from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_briefs','music_brief_versions']::text[])),
      'index', (select coalesce(jsonb_object_agg(c.relname, (select coalesce(jsonb_agg(i.indexrelid::regclass::text || ':unique=' || i.indisunique::text order by i.indexrelid::regclass::text), '[]') from pg_index i where i.indrelid = c.oid)), '{}')
                from pg_class c where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname = any(array['music_briefs','music_brief_versions']::text[])),
      'rls', (select coalesce(jsonb_object_agg(relname, relrowsecurity), '{}') from pg_class where relnamespace = 'public'::regnamespace and relkind = 'r' and relname = any(array['music_briefs','music_brief_versions']::text[])),
      'policies', (select count(*) from pg_policies where schemaname = 'public' and tablename = any(array['music_briefs','music_brief_versions']::text[])),
      'triggers', (select count(*) from pg_trigger t join pg_class c on c.oid = t.tgrelid where not t.tgisinternal and c.relnamespace = 'public'::regnamespace and c.relname = any(array['music_briefs','music_brief_versions']::text[])),
      'privileges_hors_proprietaire', (select coalesce(jsonb_object_agg(c.relname, (select coalesce(jsonb_agg(distinct case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end || ':' || x.privilege_type), '[]') from aclexplode(c.relacl) x where x.grantee <> c.relowner)), '{}')
                                       from pg_class c where c.relnamespace = 'public'::regnamespace and c.relname = any(array['music_briefs','music_brief_versions']::text[] || array['__aucune__']::text[])),
      'sequences', (select coalesce(jsonb_object_agg(s.sequencename, jsonb_build_object('type', s.data_type::text, 'debut', s.start_value, 'min', s.min_value, 'max', s.max_value, 'pas', s.increment_by, 'cycle', s.cycle)), '{}') from pg_sequences s where s.schemaname = 'public' and s.sequencename = any(array['__aucune__']::text[])),
      'fonctions', (select coalesce(jsonb_object_agg(p.oid::regprocedure::text, jsonb_build_object(
                       'md5_corps', md5(p.prosrc), 'security_definer', p.prosecdef, 'config', to_jsonb(p.proconfig), 'volatilite', p.provolatile::text,
                       'retour', format_type(p.prorettype, null), 'proprietaire', pg_get_userbyid(p.proowner),
                       'execute', (select coalesce(jsonb_agg(case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end order by case when x.grantee = 0 then 'PUBLIC' else pg_get_userbyid(x.grantee) end), '[]') from aclexplode(p.proacl) x where x.privilege_type = 'EXECUTE' and x.grantee <> p.proowner))), '{}')
                    from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = any(array['music_brief_contenu_erreur','music_admin_questionnaire','music_admin_brief_enregistrer','music_admin_brief_envoyer','music_admin_brief_suivi','music_brief_charger','music_brief_corriger','music_brief_valider']::text[]))
    ) as r)
select jsonb_pretty(jsonb_build_object(
  'migration', '022',
  'conforme', (select r from reel) = (select e from attendu),
  'sections_differentes', (select coalesce(jsonb_agg(k), '[]') from jsonb_object_keys((select e from attendu)) k where (select e from attendu)->k is distinct from (select r from reel)->k),
      'tables_vides', (select count(*) = 0 from public.music_briefs) and (select count(*) = 0 from public.music_brief_versions),
      'validation_coherente', exists (select 1 from pg_constraint where conname = 'music_briefs_validation_coherente') and exists (select 1 from pg_constraint where conname = 'music_briefs_validation_complete'),
      'colonnes_validation', (select count(*) = 3 from pg_attribute where attrelid = 'public.music_briefs'::regclass and attname in ('validated_at', 'validated_version', 'validation_consent_version') and not attnotnull),
      'fonction_validation_interne_fermee', not has_function_privilege('service_role', 'public.music_brief_contenu_erreur(jsonb)', 'execute') and not has_function_privilege('anon', 'public.music_brief_contenu_erreur(jsonb)', 'execute'),
      'sonde_contenu_vide_refuse', public.music_brief_contenu_erreur('{}'::jsonb) = 'destinataire:requis',
      'sonde_brief_lien_inconnu', public.music_brief_charger(repeat('0', 64))->>'error' = 'LIEN_INVALIDE',
      'sonde_suivi_commande_inconnue', public.music_admin_brief_suivi('CRM-99999')->>'error' = 'COMMANDE_INTROUVABLE',
      'objets_020_021_intacts', to_regclass('public.music_orders') is not null and to_regclass('public.music_questionnaires') is not null
)) as postcheck_022;
